-- ── Animations ────────────────────────────────────────────────────────────────
hl.curve("myBezier",  { type = "bezier", points = { {0.05, 0.9}, {0.1, 1.05} } })
hl.curve("easeOut",   { type = "bezier", points = { {0.0,  0.0}, {0.2,  1.0} } })

hl.animation({ leaf = "windows",    enabled = true,  speed = 7,  bezier = "myBezier" })
hl.animation({ leaf = "windowsOut", enabled = true,  speed = 4,  bezier = "default", style = "popin 80%" })
hl.animation({ leaf = "border",     enabled = true,  speed = 10, bezier = "default" })
hl.animation({ leaf = "fade",          enabled = true, speed = 4,   bezier = "easeOut" })
hl.animation({ leaf = "layers",        enabled = true, speed = 3,   bezier = "easeOut" })
hl.animation({ leaf = "layersIn",      enabled = true, speed = 3,   bezier = "easeOut", style = "fade" })
hl.animation({ leaf = "layersOut",     enabled = true, speed = 2,   bezier = "easeOut", style = "fade" })
hl.animation({ leaf = "workspaces",    enabled = true, speed = 6,   bezier = "default" })

-- The Assistant's "taking this window over" sweep: on every focus change
-- Hyprland runs the glow gradient once around the border (onFocusAnimUpdate),
-- then stops. `speed` is TENTHS OF A SECOND PER LAP and inverted — bigger is
-- slower — so 30 = one 3 s lap.
--
-- Enabled here PERMANENTLY on purpose, even though the glow itself is off
-- almost always. Two measured facts (2026-08-01, 2560x1440@144, Hyprland CPU
-- jiffies + amdgpu gpu_busy_percent, focus flips as the load):
--   · Arming it live does NOT work. Enable it under an already-open window and
--     that window never sweeps again (2.5%/1.8% GPU/CPU = idle), while a window
--     created afterwards sweeps normally (3.4%/2.8%). The animated variable is
--     built with the window, so the config has to be in place BEFORE the window
--     exists — i.e. here, not from the shell at turn start.
--   · Leaving it armed while the glow is off is FREE (1.6%/1.6% ≈ idle): with
--     nothing painted there is nothing to damage.
-- NEVER add `style = "loop"`. A loop dirties the window every tick whatever it
-- paints — measured 32% GPU permanently, the SAME with the glow disabled or at
-- alpha 0, because re-compositing means re-blurring the bar and dock on top.
hl.animation({ leaf = "glowangle",     enabled = true, speed = 30,  bezier = "linear" })


-- ── Nidara startup ─────────────────────────────────────────────────────
hl.on("hyprland.start", function()
    hl.exec_cmd("uwsm finalize")
    -- The shell runs as a systemd user unit so it respawns on crash (segfault etc.)
    -- instead of leaving a bare compositor. We START it explicitly here (the unit is
    -- intentionally NOT enabled via graphical-session.target — that would leak the UI
    -- into every Hyprland session; see bin/nidara.service). `finalize`
    -- above has just activated graphical-session.target, which the unit orders After.
    hl.exec_cmd("systemctl --user start nidara.service")
    -- Background daemons go in background-graphical.slice (-s b), not the foreground
    -- app slice: systemd deprioritizes them under CPU/IO/memory pressure and the OOM
    -- killer targets them before real apps — correct for wallpaper/idle/clipboard helpers.
    hl.exec_cmd("uwsm app -s b -- awww-daemon")
    -- Wallpaper. awww-daemon restores its own cache on startup, but that cache is
    -- NOT authoritative: it records the last `awww img` and nothing else, and the
    -- restore is ASYNCHRONOUS — the daemon builds and spawns
    -- `awww img --outputs=<out> --transition-type=none <path>` once each output is
    -- configured, so it lands some time AFTER the socket starts answering `query`.
    -- The old check here ("apply the shipped default only if nothing is being
    -- displayed") raced exactly that gap; when it won, it wrote the DEFAULT into
    -- the cache, which every later boot then faithfully restored — so the user's
    -- wallpaper was lost for good while Settings still showed it (2026-07-26).
    -- Instead: wait until every output reports an image (i.e. the daemon's own
    -- restore has landed), bounded at ~3 s for a fresh install whose cache is empty
    -- — `background_color` above covers that window — then assert the wallpaper
    -- from ~/.config/nidara/wallpaper over it. One authoritative apply, no race.
    -- The `||` is the last rung of the resolution chain: an existing but undecodable
    -- image falls through to the shipped default rather than leaving the desktop bare.
    hl.exec_cmd([==[sh -c 'i=0; while [ $i -lt 30 ]; do q=$(awww query 2>/dev/null); t=$(printf "%s\n" "$q" | grep -c .); d=$(printf "%s\n" "$q" | grep -c "image:"); [ "$t" -gt 0 ] && [ "$t" = "$d" ] && break; i=$((i+1)); sleep 0.1; done; awww img "$1" --transition-type none || awww img "$2" --transition-type none' nidara-wallpaper ]==]
        .. shquote(resolveWallpaper()) .. " " .. shquote(DEFAULT_WALLPAPER))
    hl.exec_cmd("uwsm app -s b -- /usr/lib/polkit-gnome/polkit-gnome-authentication-agent-1")
    -- GNOME keyring, secrets component only. PAM started the daemon at login holding
    -- the login password (nidara-setup wires pam_gnome_keyring into greetd) but left it
    -- deliberately uninitialized: THIS line is the `--start` it has been waiting for, and
    -- completing initialization is what unlocks the login keyring. It is not a formality —
    -- skip it and the session has secrets nobody can read. The other half of the deal is
    -- in nidara-setup: gnome-keyring-daemon.socket must be masked AND not running, or it
    -- wins the race for $XDG_RUNTIME_DIR/keyring/control and the PAM daemon exits with the
    -- password still in hand (masked-but-already-running is just as fatal as unmasked).
    -- Result: org.freedesktop.secrets for the built-in Assistant's API key plus git/VS
    -- Code/browser credentials. Secrets only (no ssh/gpg agent takeover).
    hl.exec_cmd("uwsm app -s b -- gnome-keyring-daemon --start --components=secrets")
    hl.exec_cmd("uwsm app -s b -- hypridle")
    -- TWO watchers, one per generic type — not one untyped watcher. With no --type,
    -- wl-paste picks the mime type itself, and its order (src/wl-paste.c,
    -- mime_type_to_request) is: text/plain;charset=utf-8 → text/plain → ANY text/* →
    -- only then anything else. A browser's "Copy image" offers image/png alongside a
    -- text/html or text/plain flavour of the source URL, so `try_any_text` matched
    -- first and cliphist stored the URL — every single time. Symptom the user sees:
    -- "copy image" and "copy image address" produce the same clipboard entry, and no
    -- image ever reaches the history (measured: 0 binary entries in an 82 MB, 750-item
    -- db). The image path itself was never broken — an image-ONLY offer stored fine.
    -- `--type image` is the only way to make wl-paste ask for the bitmap when text is
    -- also on offer; `--type text` reproduces today's order exactly for text offers and
    -- simply skips offers with no text at all. A copy carrying both lands twice (one
    -- text row, one image row) — that is cliphist's documented setup, and it means
    -- either flavour is one click away.
    -- -max-items 50, not cliphist's default 750. 750 is tuned for its own CLI, which
    -- is fuzzel-searchable; our panel is a scroll list with no search, so anything past
    -- ~50 rows is storage nobody can reach (prior art: Win+V keeps 25, Klipper 20).
    -- It is also a size decision now that images are stored: measured on a real 750-item
    -- history, 549 rows were under 1 KB but EIGHTEEN were over 1 MB and ate 50 of the
    -- 60 MB — the tail is what costs, and it is unbounded per item (cliphist has no
    -- max-size flag). The flag rides the store command rather than a config file so
    -- there is one place to read and nothing to keep in sync. NOTE: cliphist trims to
    -- the limit on the NEXT store, all at once — lowering this deletes the surplus
    -- immediately, it does not age out.
    hl.exec_cmd("uwsm app -s b -- wl-paste --type text --watch cliphist -max-items 50 store")
    hl.exec_cmd("uwsm app -s b -- wl-paste --type image --watch cliphist -max-items 50 store")
end)


