))

-- ── Keybinds — Hardware / media keys ─────────────────────────────────────────
-- `locked` so they keep working on the lockscreen (GNOME/KDE behaviour).
-- wpctl ships with WirePlumber; brightnessctl and playerctl are install deps.
-- brightnessctl -n floors at 1 so the "down" key can never black the screen.
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume -l 1.0 @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),        { locked = true, repeating = true })
hl.bind("XF86AudioMute",        hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),       { locked = true })
hl.bind("XF86AudioMicMute",     hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"),     { locked = true })
hl.bind("XF86MonBrightnessUp",   hl.dsp.exec_cmd("brightnessctl -n s 5%+"), { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("brightnessctl -n s 5%-"), { locked = true, repeating = true })
hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioNext",  hl.dsp.exec_cmd("playerctl next"),       { locked = true })
hl.bind("XF86AudioPrev",  hl.dsp.exec_cmd("playerctl previous"),   { locked = true })


-- ── Window rules ─────────────────────────────────────────────────────────────
hl.window_rule({
    name  = "suppress-maximize-events",
    match = { class = ".*" },
    suppress_event = "maximize",
})

hl.window_rule({
    name  = "fix-xwayland-drags",
    match = { class = "^$", title = "^$", xwayland = true, float = true, fullscreen = false, pin = false },
    no_focus = true,
})

hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },
    move  = "20 monitor_h-120",
    float = true,
})

hl.window_rule({
    name  = "steam-popups",
    match = { class = "^steam$", title = "^$" },
    rounding = 0,
    no_anim  = true,
})

hl.window_rule({
    name  = "general-popups",
    match = { class = "^$" },
    no_anim  = true,
    rounding = 0,
})

-- The Nidara "About" window (a small fixed-size GTK toplevel) floats and
-- centers. Matched by title since AGS windows share the io.Astal.ags class.
hl.window_rule({
    name   = "float-about",
    match  = { title = "^About Nidara$" },
    float  = true,
    center = true,
})


-- ── Game mode — workspace, window rules & auto-return ────────────────────────
local lastNonGameWs    = nil
local inGameSession    = false
local prevWallpaper    = nil
local prevTransition   = "fade"
local prevProfile      = nil
local gameMonitor      = ""
local activeGames      = {}   -- address → appid; tracks all Steam-launched game windows

-- Reads the active power profile. Empty string when power-profiles-daemon is not
-- installed, which is the same as "nothing to put back".
local function currentProfile()
    local p = io.popen("powerprofilesctl get 2>/dev/null")
    if not p then return "" end
    local out = p:read("*l"); p:close()
    return out and out:match("^%s*(.-)%s*$") or ""
end

local function getSteamAppId(pid)
    local p = tonumber(pid)
    for _ = 1, 8 do
        if not p or p <= 1 then break end
        local ef = io.open("/proc/" .. p .. "/environ", "rb")
        if ef then
            local env = ef:read("*a"); ef:close()
            local appid = env:match("SteamAppId=(%d+)")
                       or env:match("SteamGameId=(%d+)")
                       or env:match("STEAM_APP_ID=(%d+)")
            if appid and appid ~= "0" then return appid end
        end
        local sf = io.open("/proc/" .. p .. "/stat", "r")
        if not sf then break end
        local stat = sf:read("*l"); sf:close()
        p = tonumber(stat:match("%)%s+%S+%s+(%d+)"))
    end
    return nil
end

local function readGamingCfg()
    local f = io.open(os.getenv("HOME") .. "/.config/nidara/gaming.json", "r")
    if not f then return nil, nil, "grow", false end
    local raw = f:read("*a"); f:close()
    local mode       = raw:match('"wallpaperMode"%s*:%s*"([^"]+)"')
    local custom     = raw:match('"customWallpaper"%s*:%s*"([^"]+)"')
    local transition = raw:match('"transition"%s*:%s*"([^"]+)"') or "grow"
    local perfOn     = raw:match('"performanceProfile"%s*:%s*(true)') ~= nil
    return mode, custom, transition, perfOn
end

local function findSteamHero(appid)
    local base = os.getenv("HOME") .. "/.steam/steam/appcache/librarycache/" .. appid
    local flat = base .. "/library_hero.jpg"
    local f = io.open(flat, "r")
    if f then f:close(); return flat end
    local iter = io.popen('find "' .. base .. '" -maxdepth 2 -name "library_hero.jpg" 2>/dev/null | grep -v blur | head -1')
    if iter then
        local path = iter:read("*l"); iter:close()
        if path then path = path:match("^%s*(.-)%s*$") end
        if path and path ~= "" then return path end
    end
    return nil
end

hl.on("workspace.active", function(ws)
    if ws.name ~= "gamespace" then
        lastNonGameWs = ws.id
    end
end)

hl.on("window.open", function(w)
    local cls = w.class or ""
    local pid = w.pid or 0
    local appid = cls:match("^steam_app_(%d+)$") or getSteamAppId(pid)
    if not appid then return end

    activeGames[w.address] = appid
    hl.dispatch(hl.dsp.window.move({ workspace = "name:gamespace" }))
    hl.dispatch(hl.dsp.focus({ workspace = "name:gamespace" }))
    hl.exec_cmd("hyprctl setprop address:" .. w.address .. " immediate 1 lock:0")

    -- "Already in a game session" — one flag, not `prevWallpaper`. That variable is
    -- only set when a wallpaper was actually swapped, so with mode = none (or
    -- artwork with no hero art found) a second game window re-ran this whole block.
    -- Harmless while the only thing it repeated was setting the profile to
    -- performance; not harmless now that entering CAPTURES the profile to put back,
    -- since the second pass would capture "performance" and restore that on exit.
    if inGameSession then return end
    inGameSession = true

    local ws = hl.get_active_workspace()
    local mon = ws and ws.monitor
    gameMonitor = (type(mon) == "string" and mon ~= "") and mon or ""

    local mode, custom, transition, perfOn = readGamingCfg()
    if perfOn then
        -- Remember what to go back to, exactly like the wallpaper below. Exit used
        -- to hard-code `balanced`, so a session started from Power saver ended in
        -- Balanced and the Settings choice was simply gone, silently.
        prevProfile = currentProfile()
        hl.exec_cmd("powerprofilesctl set performance")
    end

    local wallpaperPath = nil
    if mode == "artwork" then
        wallpaperPath = findSteamHero(appid)
    elseif mode == "custom" and custom and custom ~= "" then
        wallpaperPath = custom
    end

    if wallpaperPath then
        prevWallpaper, prevTransition = readWallpaperCfg()
        local outputFlag = (gameMonitor ~= "") and (" --outputs " .. gameMonitor) or ""
        -- No transition on entry: game covers the wallpaper immediately anyway,
        -- animating it causes awww to freeze mid-transition until the game closes.
        os.execute("awww img " .. wallpaperPath .. " --transition-type none" .. outputFlag)
    end
end)

hl.on("window.destroy", function(w)
    if not activeGames[w.address] then return end
    activeGames[w.address] = nil

    hl.timer(function()
        local hasMore = false
        for _ in pairs(activeGames) do hasMore = true; break end
        if hasMore then return end

        -- UNDOING THE SESSION and PUTTING THE USER BACK are two different jobs, and
        -- they used to share one condition. Everything below hung off "the user is
        -- standing on gamespace right now" — so quitting a game after wandering to
        -- another workspace left the game wallpaper up and the machine on
        -- performance, with the session flags still set, so the NEXT game got no
        -- entry either. Undoing is unconditional; only the focus return depends on
        -- where the user happens to be.
        inGameSession = false
        -- Put back what we found, not a guess. Only when the profile is STILL the
        -- one we set: if the user picked something else while the game ran, that is
        -- a newer decision than ours and restoring would undo it.
        if prevProfile and prevProfile ~= "" and currentProfile() == "performance" then
            hl.exec_cmd("powerprofilesctl set " .. prevProfile)
        end
        prevProfile = nil
        if prevWallpaper then
            local outputFlag = (gameMonitor ~= "") and (" --outputs " .. gameMonitor) or ""
            os.execute("awww img " .. prevWallpaper .. " --transition-type " .. prevTransition .. outputFlag)
            prevWallpaper = nil
        end

        local activeWs = hl.get_active_workspace()
        if lastNonGameWs ~= nil and activeWs and activeWs.name == "gamespace" then
            hl.dispatch(hl.dsp.focus({ workspace = lastNonGameWs }))
        end
    end, { timeout = 3000, type = "oneshot" })
end)


hl.workspace_rule({
    workspace    = "name:gamespace",
    gaps_in      = 0,
    gaps_out     = 0,
    no_border    = true,
    border_size  = 0,
    no_rounding  = true,
    no_shadow    = true,
    decorate     = false,
    persistent   = false,
    animation    = "fade",
})

-- All windows on gamespace get full performance treatment regardless of class
hl.window_rule({
    name         = "gamespace-perf",
    match        = { workspace = "name:gamespace" },
    no_blur      = true,
    no_anim      = true,
    no_dim       = true,
    no_shadow    = true,
    rounding     = 0,
    border_size  = 0,
    opaque       = true,
    force_rgbx   = true,
    immediate    = true,
    idle_inhibit = "focus",
    decorate     = false,
})

-- Fallback workspace assignment for steam_app_* (belt+suspenders with the Lua handler)
hl.window_rule({
    name      = "steam-games-to-gamespace",
    match     = { class = "^steam_app_" },
    workspace = "name:gamespace",
})

-- Also catch games that self-report content type (XDG game = 3)
hl.window_rule({
    name      = "content-game-to-gamespace",
    match     = { content = 3 },
    workspace = "name:gamespace",
})


-- ── Layer rules ───────────────────────────────────────────────────────────────
-- nidara-bar at 0.01 (was 0.05): during the overlays' close animation the glass
-- alpha drops below the threshold and the backdrop blur pops off; at 0.01 that
-- happens when the panel is already near-invisible. Verified no AA-edge halos
-- at rest.
-- blur_popups: the `blur` rule only blurs the layer SURFACE (and the Gtk.Overlay
-- children drawn on it — CC/NC/system menu/overview). Popups of the layer (a
-- Gtk.Popover: the glass tooltip, the dock context menu) are SEPARATE surfaces,
-- blurred by this rule — NOT by `decoration:blur:popups`, which only covers
-- popups of WINDOWS. Their content must clear `popups_ignorealpha` (0.30); the
-- tooltip floors its glass at 0.38 for exactly that. See tech-debt #26.
-- nidara-island: the Activity Island's expanded modes live in their OWN surface
-- on the OVERLAY level, one above the bar's TOP. That is the whole point: a
-- surface's blur samples what was composited BEFORE it, so this rule is what
-- finally difumina the bar's capsules under the island. Inside one window it
-- was impossible — Cairo has no backdrop-filter, so at the default 0.05 glass
-- the capsules read through sharp (see ui/shell/surfaces/island/IslandWindow.ts).
-- 0.01 like the bar, NOT the 0.30 a popup would need: `ignore_alpha` and
-- `popups_ignorealpha` are different knobs, which is why the island keeps its
-- 0.05 glass and stays tied to the user's opacity setting.
-- It needs `blur_popups` for the same reason the bar does, and shipped without
-- it: while the island lived inside the bar's window its popups were the BAR's
-- popups and this rule covered them. Moving it to its own surface moved them
-- too, and the player panel's source menu came out unblurred (user-caught
-- 2026-08-03). Any layer that can open a Gtk.Popover needs the flag.
-- nidara-app-grid: the app grid got its OWN surface on 2026-08-09 (it used to be a
-- child of the dock's window, which had to hand its whole blur region back for as
-- long as the grid was up — see AppGridWindow.ts). It keeps the DOCK's 0.04 rather
-- than the bar's 0.01 on purpose: 0.04 is what it has been blurred at all along,
-- and the reason the dock is not at 0.01 is app ICONS haloing, which is most of
-- what this surface paints. It opens context menus, hence blur_popups — the exact
-- flag the island shipped without when IT moved out of the bar.
hl.layer_rule({ match = { namespace = "nidara-bar" },      blur = true, blur_popups = true, ignore_alpha = 0.01  })
hl.layer_rule({ match = { namespace = "nidara-island" },   blur = true, blur_popups = true, ignore_alpha = 0.01  })
hl.layer_rule({ match = { namespace = "nidara-dock" },     blur = true, blur_popups = true, ignore_alpha = 0.04 })
hl.layer_rule({ match = { namespace = "nidara-app-grid" }, blur = true, blur_popups = true, ignore_alpha = 0.04 })
hl.layer_rule({ match = { namespace = "nidara-lock" },     blur = true, ignore_alpha = 0.3   })


-- ── Lock screen submap ────────────────────────────────────────────────────────
-- nidara-lock activates with:  hyprctl dispatch 'hl.dsp.submap("lock")'
-- nidara-lock resets with:     hyprctl dispatch 'hl.dsp.submap("reset")'
hl.define_submap("lock", function()
    hl.bind("SUPER + SHIFT + CTRL + ALT + Escape", hl.dsp.submap("reset"))
end)


